#include <stdio.h>
#define PI 3.14159

int main()
{
    float r = 5.0;
    printf("Area = %.2f\n", PI * r * r);
    return 0;
}

#include <stdio.h>

int main()
{
    int a, b, sum;
    printf("Enter two integers: ");
    scanf("%d %d", &a, &b);
    sum = a + b;
    printf("Sum = %d\n", sum);
    return 0;
}

#include <stdio.h>

int main()
{
    int mark;
    printf("Enter mark: ");
    scanf("%d", &mark);

    if (mark >= 80)
        printf("Distinction\n");
    else if (mark >= 60)
        printf("First division\n");
    else if (mark >= 40)
        printf("Passed\n");
    else
        printf("Failed\n");

    return 0;
}

#include <stdio.h>

int main()
{
    int day;
    printf("Enter day number (1-7): ");
    scanf("%d", &day);

    switch (day)
    {
        case 1: printf("Sunday\n");    break;
        case 2: printf("Monday\n");    break;
        case 3: printf("Tuesday\n");   break;
        case 4: printf("Wednesday\n"); break;
        case 5: printf("Thursday\n");  break;
        case 6: printf("Friday\n");    break;
        case 7: printf("Saturday\n");  break;
        default: printf("Invalid day\n");
    }
    return 0;
}

#include <stdio.h>

int main()
{
    int i;

    /* for: print 1 to 5 */
    for (i = 1; i <= 5; i++)
        printf("%d ", i);
    printf("\n");

    /* while: same, written differently */
    i = 1;
    while (i <= 5)
    {
        printf("%d ", i);
        i++;
    }
    printf("\n");

    return 0;
}

#include <stdio.h>

int main()
{
    int n, i;

    printf("Enter a number: ");
    scanf("%d", &n);

    printf("Multiplication table of %d:\n", n);
    for (i = 1; i <= 10; i++)
        printf("%d x %d = %d\n", n, i, n * i);

    return 0;
}

#include <stdio.h>

int main()
{
    int i, j;
    for (i = 1; i <= 3; i++)
    {
        for (j = 1; j <= 3; j++)
            printf("%d ", i * j);
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

int main()
{
    int a[5], i, sum = 0;

    printf("Enter 5 numbers: ");
    for (i = 0; i < 5; i++)
        scanf("%d", &a[i]);

    for (i = 0; i < 5; i++)
        sum = sum + a[i];

    printf("Sum = %d\n", sum);
    printf("Average = %.2f\n", sum / 5.0);
    return 0;
}

#include <stdio.h>

int main()
{
    int a[2][3] = {{1, 2, 3}, {4, 5, 6}};
    int i, j;

    for (i = 0; i < 2; i++)
    {
        for (j = 0; j < 3; j++)
            printf("%d ", a[i][j]);
        printf("\n");
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

int main()
{
    char name[20];
    int i, len;

    printf("Enter your name: ");
    scanf("%s", name);

    len = strlen(name);
    printf("Length = %d\n", len);

    printf("Reversed: ");
    for (i = len - 1; i >= 0; i--)
        putchar(name[i]);
    printf("\n");

    return 0;
}

